#!/usr/bin/env bash
#
# contracts/plonky2-pin.json: the content of the pinned polygon-plonky2 Solidity, readable by Forge.
#
# WHY. `git pull` and `git checkout` move the gitlink of contracts/lib/polygon-plonky2 but NOT the
# checkout inside it. A clone updated that way compiles the NEW contracts against the OLD verifier
# and `forge test` fails dozens of tests with messages that never mention the submodule
# ("fixture: v2 WHIR PoW", InvalidMleVerifierConfiguration(), a compact length off by 7 KB). Forge
# cannot read git, so this manifest records, for the pinned commit, the SHA-256 of every Solidity
# file Forge compiles from the submodule (`@mle/` = mle/contracts/src). `Plonky2Pin.requirePinned()`
# (contracts/script/Plonky2Pin.sol) recomputes them before any real-proof verifier is deployed and
# stops with the one command that fixes it. The Rust side has the same check in build.rs.
#
# Usage:
#   .github/ci/plonky2-pin.sh write   # after staging a submodule bump: git add contracts/lib/polygon-plonky2
#   .github/ci/plonky2-pin.sh check   # CI (verify-pinned-inputs.sh): the manifest describes the staged pin
#
# The pin is the gitlink in the INDEX, so `write` follows a bump as soon as it is staged, and
# `check` catches a commit that bumped the submodule without regenerating the manifest. Both read
# blobs from the pinned commit, never from the working tree: a dirty or stale checkout cannot leak
# into the manifest.

set -euo pipefail

fail() { printf '\n[plonky2-pin] FAIL: %s\n' "$*" >&2; exit 1; }

mode="${1:-}"
case "$mode" in write|check) ;; *) fail "usage: $0 write|check" ;; esac

cd "$(git rev-parse --show-toplevel)"

SUB=contracts/lib/polygon-plonky2
SRC=mle/contracts/src
MANIFEST=contracts/plonky2-pin.json

pin="$(git ls-files -s -- "$SUB" | awk '$1 == "160000" { print $2 }')"
[ -n "$pin" ] || fail "$SUB is not a submodule gitlink in the index"
git -C "$SUB" cat-file -e "$pin^{commit}" 2>/dev/null \
    || fail "$SUB does not have the pinned commit $pin. Run: git submodule update --init --recursive"

if command -v sha256sum >/dev/null 2>&1; then sha256() { sha256sum | awk '{ print $1 }'; }
else sha256() { shasum -a 256 | awk '{ print $1 }'; }
fi

paths=()
while IFS= read -r p; do paths+=("$p"); done < <(git -C "$SUB" ls-tree -r --name-only "$pin" -- "$SRC" | LC_ALL=C sort)
[ "${#paths[@]}" -gt 0 ] || fail "the pinned commit $pin has no files under $SRC"

out="$(mktemp "${TMPDIR:-/tmp}/plonky2-pin.XXXXXX")"
trap 'rm -f "$out"' EXIT
{
    printf '{\n'
    printf '  "note": "GENERATED by .github/ci/plonky2-pin.sh write. SHA-256 of every Solidity file Forge compiles from the pinned polygon-plonky2 commit; contracts/script/Plonky2Pin.sol refuses a checkout that differs.",\n'
    printf '  "submodule": "%s",\n' "$SUB"
    printf '  "commit": "%s",\n' "$pin"
    printf '  "fix": "git submodule update --init --recursive",\n'
    printf '  "paths": [\n'
    for i in "${!paths[@]}"; do
        sep=','; [ "$i" -eq $(( ${#paths[@]} - 1 )) ] && sep=''
        printf '    "lib/polygon-plonky2/%s"%s\n' "${paths[$i]}" "$sep"
    done
    printf '  ],\n'
    printf '  "sha256": [\n'
    for i in "${!paths[@]}"; do
        sep=','; [ "$i" -eq $(( ${#paths[@]} - 1 )) ] && sep=''
        h="$(git -C "$SUB" cat-file blob "$pin:${paths[$i]}" | sha256)"
        printf '    "0x%s"%s\n' "$h" "$sep"
    done
    printf '  ]\n'
    printf '}\n'
} > "$out"

if [ "$mode" = write ]; then
    cp "$out" "$MANIFEST"
    echo "[plonky2-pin] wrote $MANIFEST for $SUB @ $pin (${#paths[@]} files)"
    exit 0
fi

[ -f "$MANIFEST" ] || fail "$MANIFEST is missing. Run: .github/ci/plonky2-pin.sh write"
if ! cmp -s "$out" "$MANIFEST"; then
    diff -u "$MANIFEST" "$out" >&2 || true
    fail "$MANIFEST does not describe the pinned $SUB @ $pin. A submodule bump must regenerate it: \
.github/ci/plonky2-pin.sh write"
fi

# foundry.lock is what `forge install` / `forge update` read. It must name the same commits as the
# gitlinks, or a Foundry that honours the lock checks out code this repo never tested.
python3 - "$pin" "$(git ls-files -s -- contracts/lib/forge-std | awk '{ print $2 }')" <<'PY' \
    || fail "contracts/foundry.lock disagrees with the submodule gitlinks (see above)"
import json, sys
plonky2, forge_std = sys.argv[1], sys.argv[2]
lock = json.load(open("contracts/foundry.lock"))
want = {"lib/polygon-plonky2": plonky2, "lib/forge-std": forge_std}
bad = False
if set(lock) != set(want):
    print(f"foundry.lock entries {sorted(lock)} != submodules {sorted(want)}", file=sys.stderr)
    bad = True
for path, rev in want.items():
    entry = lock.get(path, {})
    got = entry.get("rev") or entry.get("branch", {}).get("rev")
    if got != rev:
        print(f"foundry.lock {path} rev {got} != gitlink {rev}", file=sys.stderr)
        bad = True
sys.exit(1 if bad else 0)
PY
echo "[plonky2-pin] ok: $MANIFEST and contracts/foundry.lock match $SUB @ $pin (${#paths[@]} files)"
